#include <stdlib.h>
#include <string.h>

// plist_t is assumed to be a structure representing a plist node.
typedef struct {
    char *string;
    size_t length;
} plist_t;

plist_t* parse_string_node(const char **bnode, uint64_t size) {
    // Allocate memory for the plist node
    plist_t *node = (plist_t*)malloc(sizeof(plist_t));
    if (!node) {
        return NULL; // Allocation failed
    }

    // Allocate memory for the string (plus one for null-terminator)
    node->string = (char*)malloc(size + 1);
    if (!node->string) {
        free(node);
        return NULL; // Allocation failed
    }

    // Ensure size is within reasonable bounds to prevent overflow
    if (size > SIZE_MAX - 1) {
        free(node->string);
        free(node);
        return NULL; // Size is too large
    }

    // Copy the string data from the byte node
    size_t copy_size = size < strlen(*bnode) ? size : strlen(*bnode);
    strncpy(node->string, *bnode, copy_size);

    // Null-terminate the string
    node->string[copy_size] = '\0';

    // Update the length of the string
    node->length = copy_size;

    return node;
}
